  return <ScreenShell><Header title="Language" onBack={()=>actions.go('settings')}/><ScrollView style={styles.flex} contentContainerStyle={styles.scroll}><View style={styles.languageHero}><Image source={uiAssets.language} style={styles.languageImage} resizeMode="contain"/><Text style={styles.heroTitle}>Choose your language</Text><Text style={styles.heroBody}>You can change this at any time.</Text></View><RoundedCard>{langs.map(x=><Pressable key={x} onPress={()=>setLanguage(x)} style={styles.languageRow}><Text style={styles.languageName}>{x}</Text><View style={[styles.radio,language===x&&styles.radioActive]}>{language===x?<View style={styles.radioDot}/>:null}</View></Pressable>)}</RoundedCard><PrimaryButton label="Apply language" onPress={()=>{Alert.alert('Language updated',language);actions.go('settings')}}/></ScrollView></ScreenShell>;
