export function VerificationScreen({ actions }: { data: V41FrontendData; actions: V41FrontendActions }) {
  const [code,setCode]=useState('');
  return <ScreenShell><Header title="Verification" onBack={()=>actions.go('forgotPassword')}/><ScrollView style={styles.flex} contentContainerStyle={styles.scroll}><View style={styles.centerHero}><View style={styles.authIcon}><Ionicons name="shield-checkmark-outline" size={34}/></View><Text style={styles.heroTitle}>Enter verification code</Text><Text style={styles.heroBody}>We sent a 6-digit code to your selected contact method.</Text></View><TextInput value={code} onChangeText={x=>setCode(x.replace(/\D/g,'').slice(0,6))} placeholder="000000" placeholderTextColor={COLORS.mutedLight} keyboardType="number-pad" style={styles.codeInput}/><Pressable onPress={()=>Alert.alert('Code sent','A new verification code has been requested.')}><Text style={styles.centerAction}>Resend code</Text></Pressable><PrimaryButton disabled={code.length!==6} label="Verify" onPress={()=>actions.go('resetPassword')}/></ScrollView></ScreenShell>;
}

export function ResetPasswordScreen({ actions }: { data: V41FrontendData; actions: V41FrontendActions }) {
  const [password,setPassword]=useState(''); const [confirm,setConfirm]=useState('');
  return <ScreenShell><Header title="New password" onBack={()=>actions.go('verification')}/><ScrollView style={styles.flex} contentContainerStyle={styles.scroll}><Text style={styles.bigTitle}>Create a new password</Text><Text style={styles.heroBody}>Use at least 8 characters and avoid reusing a password from another service.</Text><TextInput value={password} onChangeText={setPassword} placeholder="New password" placeholderTextColor={COLORS.muted} secureTextEntry style={styles.input}/><TextInput value={confirm} onChangeText={setConfirm} placeholder="Confirm password" placeholderTextColor={COLORS.muted} secureTextEntry style={styles.input}/><PrimaryButton disabled={password.length<8||password!==confirm} label="Save password" onPress={()=>{Alert.alert('Password changed','You can now sign in with your new password.');actions.go('signIn')}}/></ScrollView></ScreenShell>;
}

export function GlobalCartScreen({ data, actions }: { data: V41FrontendData; actions: V41FrontendActions }) {
  const [foodQty,setFoodQty]=useState(2); const [shopQty,setShopQty]=useState(1); const total=foodQty*13000+shopQty*32000;
  return <ScreenShell><Header title="Global cart" onBack={()=>actions.go('home')}/><ScrollView style={styles.flex} contentContainerStyle={styles.scroll}><Text style={styles.heroBody}>The donor app keeps carts from different stores visible together while checkout remains grouped by merchant.</Text><SectionTitle title="Cafe Javas"/><RoundedCard style={styles.globalCartGroup}><CartLine title="Chicken sandwich" meta="Regular" price={formatMoney(data.country,13000*foodQty)} qty={foodQty} setQty={setFoodQty}/><Pressable onPress={()=>actions.go('foodCheckout')} style={styles.cartCheckout}><Text style={styles.cartCheckoutText}>Checkout food order</Text><Feather name="arrow-right" size={17} color={COLORS.white}/></Pressable></RoundedCard><SectionTitle title="Goodlife Pharmacy"/><RoundedCard style={styles.globalCartGroup}><CartLine title="Daily wellness pack" meta="Standard pack" price={formatMoney(data.country,32000*shopQty)} qty={shopQty} setQty={setShopQty}/><Pressable onPress={()=>actions.go('commerceCheckout')} style={styles.cartCheckout}><Text style={styles.cartCheckoutText}>Checkout shop order</Text><Feather name="arrow-right" size={17} color={COLORS.white}/></Pressable></RoundedCard><RoundedCard style={styles.summaryCard}><SummaryRow label="Across carts" value={formatMoney(data.country,total)} strong/></RoundedCard></ScrollView></ScreenShell>;
}
function CartLine({title,meta,price,qty,setQty}:{title:string;meta:string;price:string;qty:number;setQty:(v:number)=>void}){return <View style={styles.cartLine}><View style={styles.cartLineIcon}><Ionicons name="bag-handle-outline" size={23}/></View><View style={styles.flex}><Text style={styles.storeName}>{title}</Text><Text style={styles.storeMeta}>{meta}</Text><Text style={styles.productPrice}>{price}</Text></View><View style={styles.qtyControl}><Pressable onPress={()=>setQty(Math.max(0,qty-1))}><Feather name="minus" size={16}/></Pressable><Text style={styles.qtyText}>{qty}</Text><Pressable onPress={()=>setQty(qty+1)}><Feather name="plus" size={16}/></Pressable></View></View>}

export function OfflinePaymentScreen({ data, actions }: { data: V41FrontendData; actions: V41FrontendActions }) {
  const [method,setMethod]=useState('Bank transfer'); const [reference,setReference]=useState('');
  return <ScreenShell><Header title="Offline payment" onBack={()=>actions.go('paymentMethods')}/><ScrollView style={styles.flex} contentContainerStyle={styles.scroll}><View style={styles.offlineHero}><Ionicons name="receipt-outline" size={40}/><View style={styles.flex}><Text style={styles.heroTitle}>Pay using an offline method</Text><Text style={styles.heroBody}>Submit your payment reference so the merchant can verify it.</Text></View></View><View style={styles.chipWrap}>{['Bank transfer','Agent deposit','Pay at counter'].map(x=><V41Chip key={x} label={x} active={method===x} onPress={()=>setMethod(x)}/>)}</View><RoundedCard style={styles.bankCard}><Text style={styles.heroEyebrow}>PAYMENT INSTRUCTIONS</Text><Text style={styles.storeName}>Kareebu settlement account</Text><Text style={styles.bodyCopy}>Use your order ID as the payment narration. Verification happens before fulfilment begins.</Text></RoundedCard><TextInput value={reference} onChangeText={setReference} placeholder="Payment reference / transaction ID" placeholderTextColor={COLORS.muted} style={styles.input}/><PrimaryButton disabled={!reference.trim()} label="Submit payment proof" onPress={()=>actions.go('orderDetails')}/></ScrollView></ScreenShell>;
}

export function PaymentProcessingScreen({ actions }: { data: V41FrontendData; actions: V41FrontendActions }) {
  const [processing,setProcessing]=useState(false);
  return <ScreenShell><Header title="Secure payment" onBack={()=>actions.go('paymentMethods')}/><ScrollView style={styles.flex} contentContainerStyle={styles.scroll}><View style={styles.webPayment}><View style={styles.webBar}><Ionicons name="lock-closed" size={16} color={COLORS.green}/><Text style={styles.webUrl}>secure.kareebu.pay</Text></View><View style={styles.webBody}><Ionicons name="card-outline" size={52}/><Text style={styles.heroTitle}>Complete your payment</Text><Text style={[styles.heroBody,{textAlign:'center'}]}>This represents the secure payment-webview surface used by the donor app for external gateways.</Text></View></View><PrimaryButton label={processing?'Processing…':'Authorise payment'} disabled={processing} onPress={()=>{setProcessing(true);setTimeout(()=>actions.go('commerceOrderSuccess'),650)}}/><Pressable onPress={()=>actions.go('paymentFailed')}><Text style={styles.centerAction}>Preview failed payment state</Text></Pressable></ScrollView></ScreenShell>;
}

export function RidePaymentScreen({ data, actions }: { data: V41FrontendData; actions: V41FrontendActions }) {
  const [method,setMethod]=useState('MTN Mobile Money'); const methods=['MTN Mobile Money','Airtel Money','Visa •••• 4242','Cash'];
  return <ScreenShell><Header title="Ride payment" onBack={()=>actions.go('confirmBooking')}/><ScrollView style={styles.flex} contentContainerStyle={styles.scroll}><RoundedCard style={styles.rideFareCard}><Text style={styles.heroEyebrow}>TRIP FARE</Text><Text style={styles.rideFareAmount}>{formatMoney(data.country,8500)}</Text><Text style={styles.storeMeta}>Final fare may change if the trip route or waiting time changes.</Text></RoundedCard><SectionTitle title="Choose payment method"/><RoundedCard>{methods.map(x=><Pressable key={x} onPress={()=>setMethod(x)} style={styles.paymentRow}><View style={styles.paymentIcon}><Ionicons name={x==='Cash'?'cash-outline':x.startsWith('Visa')?'card-outline':'phone-portrait-outline'} size={23}/></View><Text style={styles.paymentName}>{x}</Text><View style={[styles.radio,method===x&&styles.radioActive]}>{method===x?<View style={styles.radioDot}/>:null}</View></Pressable>)}</RoundedCard><PrimaryButton label="Confirm & request driver" onPress={()=>actions.go('driver')}/></ScrollView></ScreenShell>;
}

function SummaryRow({label,value,strong}:{label:string;value:string;strong?:boolean}){return <View style={styles.summaryRow}><Text style={[styles.summaryLabel,strong&&styles.summaryStrong]}>{label}</Text><Text style={[styles.summaryValue,strong&&styles.summaryStrong]}>{value}</Text></View>}
function Benefit({text}:{text:string}){return <View style={styles.benefit}><View style={styles.benefitCheck}><Feather name="check" size={13} color={COLORS.black}/></View><Text style={styles.benefitText}>{text}</Text></View>}
function Stat({value,label}:{value:string;label:string}){return <View style={styles.stat}><Text style={styles.statValue}>{value}</Text><Text style={styles.statLabel}>{label}</Text></View>}
function ServiceLine({title,price}:{title:string;price:string}){return <View style={styles.serviceLine}><Text style={styles.serviceTitle}>{title}</Text><Text style={styles.servicePrice}>{price}</Text></View>}

